// #155 AC-3 -- the candidate page's "Parsed fields" table, rendered from the candidate API's real output for the
// complete and the sparse résumé (generated by the backend: scripts/gen-profile-fields-fixture.cjs, kept in sync
// by its test): every field's value, status and source location as the API gave them, and the same page again
// after a reload (the payload read anew).
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { bundleRender, textOf } from "./renderComponent.mjs";

const read = () => JSON.parse(readFileSync(new URL("./fixtures/profile-fields.json", import.meta.url), "utf8"));
const render = await bundleRender(`
  import { createElement } from "react";
  import { renderToStaticMarkup } from "react-dom/server";
  import { ParsedFieldsTable } from "./src/features/candidates/ParsedFieldsCard.tsx";
  export const render = (fields, lang = "en") => renderToStaticMarkup(createElement(ParsedFieldsTable, { fields, t: (s) => s, lang, onOpen: () => {} }));
`);
const rowOf = (html, field) => html.match(new RegExp(`<tr data-field="${field}"[^>]*>(.*?)</tr>`))?.[1] ?? "";

test("#155 AC-3: the complete résumé — every field rendered with the API's values, status and source locations", () => {
  const fields = read().complete;
  const html = render(fields);
  assert.equal(html.match(/<tr data-field=/g)?.length, 12, "all twelve §4.1 fields");
  for (const field of fields) {
    const row = rowOf(html, field.field);
    assert.match(html, new RegExp(`<tr data-field="${field.field}" data-status="${field.status}"`), field.field);
    for (const value of field.values) assert.ok(textOf(row).includes(textOf(value)), `${field.field}: ${value}`);
    for (const evidence of field.evidence) assert.ok(row.includes(`data-segment-id="${evidence.segmentId}"`), `${field.field}: link to ${evidence.segmentId}`);
  }
  assert.ok(fields.every((f) => f.status === "known"), "the complete sample reads every field");
});

test("#155 AC-3: the sparse résumé — what it doesn't give is shown as not provided, with no made-up value or link", () => {
  const fields = read().sparse;
  const html = render(fields);
  for (const field of fields.filter((f) => f.status === "missing")) {
    const row = rowOf(html, field.field);
    assert.ok(textOf(row).includes("Not provided"), field.field);
    assert.ok(!row.includes("data-segment-id="), `${field.field}: no source link`);
  }
  assert.ok(fields.filter((f) => f.status === "missing").length >= 8, "the sparse sample leaves most fields out");
});

test("#155 AC-3: a reload shows the same page — the same fields, statuses and locations", () => {
  const first = render(read().complete);
  const reloaded = render(read().complete);
  assert.equal(reloaded, first);
  assert.equal(render(read().sparse), render(read().sparse));
});
